WITH next_results AS ( SELECT id_tournament,id_user,rank() OVER(ORDER BY time)::integer AS next_rank FROM public.track_tournament_result WHERE id_tournament=$1 ), scored AS ( SELECT id_tournament,id_user,next_rank, greatest(2,(2*ceil((1000*power(0.96,next_rank-1))/2))::integer) AS next_points FROM next_results ) UPDATE public.track_tournament_result result SET rank=scored.next_rank,points=scored.next_points,date_updated=clock_timestamp() FROM scored WHERE result.id_tournament=scored.id_tournament AND result.id_user=scored.id_user AND row(result.rank,result.points) IS DISTINCT FROM row(scored.next_rank,scored.next_points)
